/* the marks: 16px discs 16px in from the card's edge, centred on the step's first line, under the header's mark */
:root[data-style="clean"] .dm-tk-st .dm-mk,:root [data-style="clean"] .dm-tk-st .dm-mk,:root [data-style="clean"].dm-tk-st .dm-mk{width:16px;height:16px;margin:2px 2px 0 0;color:var(--dm-fg);background:none;transition:none}
