:root[data-style="clean"] .dm-tk-st.dm-retry .dm-mk .dm-i,:root [data-style="clean"] .dm-tk-st.dm-retry .dm-mk .dm-i,:root [data-style="clean"].dm-tk-st.dm-retry .dm-mk .dm-i{width:16px;height:16px;stroke-width:1.8}
