@keyframes dm-tkdraw{from{stroke-dashoffset:21}}
/* the hairline from under each mark to just above the next, darkening down into the next step once this one is done */
:root[data-style="clean"] .dm-tk-st:not(:last-child)::before,:root [data-style="clean"] .dm-tk-st:not(:last-child)::before,:root [data-style="clean"].dm-tk-st:not(:last-child)::before,:root[data-style="clean"] .dm-tk-st.dm-done:not(:last-child)::after,:root [data-style="clean"] .dm-tk-st.dm-done:not(:last-child)::after,:root [data-style="clean"].dm-tk-st.dm-done:not(:last-child)::after{left:7.5px;top:27px;bottom:-3px;width:1px;border-radius:0;background:var(--dm-line)}
:root[data-style="clean"] .dm-tk-st.dm-done:not(:last-child)::after,:root [data-style="clean"] .dm-tk-st.dm-done:not(:last-child)::after,:root [data-style="clean"].dm-tk-st.dm-done:not(:last-child)::after{background:var(--dm-line-strong);animation:dm-tkgrow .44s var(--dm-ease-io) .2s backwards}
/* what a step found writes itself in a word at a time: a fade and a 3px rise, no blur */
@keyframes dm-tkwordc{from{opacity:0;transform:translateY(3px)}}
:root[data-style="clean"] .dm-tk-st .dm-res .dm-w,:root [data-style="clean"] .dm-tk-st .dm-res .dm-w,:root [data-style="clean"].dm-tk-st .dm-res .dm-w{animation:dm-tkwordc .42s var(--dm-ease) backwards}
